{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#faf7f5;--accent:#6b4cff;--muted:#675a5a;--card:#fff;--glass:rgba(255,255,255,0.6);--shadow:0 6px 18px rgba(32,24,40,0.08)}
    *{box-sizing:border-box;font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, 'Helvetica Neue', Arial}
    html,body{height:100%;margin:0;background:linear-gradient(180deg,var(--bg) 0%,#fff 100%);color:#2b2b2b}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 32px}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:48px;height:48px;border-radius:10px;background:linear-gradient(135deg,#fff,#efe8ff);display:flex;align-items:center;justify-content:center;box-shadow:var(--shadow)}
    .logo svg{width:28px;height:28px}
    nav{display:flex;gap:12px;align-items:center}
    nav a{color:var(--muted);text-decoration:none;padding:8px 12px;border-radius:8px}
    nav a.active,nav a:hover{background:var(--card);box-shadow:var(--shadow);color:#1c1630}
    main{max-width:1100px;margin:28px auto;padding:32px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:start}
    .hero-card{background:var(--card);padding:28px;border-radius:14px;box-shadow:var(--shadow)}
    h1{margin:0 0 8px;font-size:28px}
    p.lead{margin:0;color:var(--muted)}

    /* Mood selector */
    .mood{margin-top:18px}
    .mood .chips{display:flex;gap:8px;flex-wrap:wrap}
    .chip{padding:10px 12px;border-radius:999px;background:linear-gradient(180deg,#fff,#f6f3ff);cursor:pointer;border:1px solid rgba(107,76,255,0.08)}
    .chip.active{background:var(--accent);color:#fff;box-shadow:0 8px 20px rgba(107,76,255,0.12)}

    /* Recommendation box */
    .recommend{margin-top:16px;padding:18px;border-radius:12px;background:linear-gradient(180deg,#fff,#faf6ff);display:flex;align-items:center;gap:12px}
    .rec-title{font-weight:600}
    .rec-desc{color:var(--muted);font-size:14px}
    .cta{margin-left:auto}
    .btn{padding:10px 16px;border-radius:10px;background:var(--accent);color:#fff;border:none;cursor:pointer}

    /* Pricing comparator */
    .pricing{margin-top:20px;background:linear-gradient(180deg,#fff,#fbfbff);padding:16px;border-radius:12px;border:1px solid rgba(107,76,255,0.06)}
    .toggle{display:inline-flex;padding:4px;background:rgba(27,24,36,0.04);border-radius:999px}
    .toggle button{border:0;background:transparent;padding:6px 10px;border-radius:999px;cursor:pointer}
    .toggle button.active{background:var(--accent);color:#fff}
    .plan-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:12px}
    .plan{background:var(--card);padding:14px;border-radius:12px;box-shadow:var(--shadow)}
    .plan .price{font-size:20px;font-weight:700}
    .muted{color:var(--muted);font-size:13px}

    footer{margin-top:28px;padding:18px;text-align:center;color:var(--muted);font-size:13px}

    /* subtle pattern */
    .pattern{position:fixed;right:0;bottom:0;opacity:0.08;pointer-events:none}

    @media (max-width:880px){.hero{grid-template-columns:1fr}.brand span{display:none}}
  </style>
</head>
<body>
  <header>
    <div class="brand"><div class="logo" aria-hidden>
      <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="3" width="18" height="18" rx="6" fill="#F7F3FF"/><path d="M7 12c1.333-3 3.667-3 5 0 1.333 3 3.667 3 5 0" stroke="#6B4CFF" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>
    </div><span><strong>{{BUSINESS_NAME}}</strong><div style="font-size:12px;color:var(--muted)">Aromatherapy • {{CITY}}, {{STATE}}</div></span></div>
    <nav>
      <a href="index.html">Explore</a>
      <a class="active" href="services.html">Offerings</a>
      <a href="blends.html">Blends & Rituals</a>
      <a href="shop.html">Store</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">Story</a>
      <a href="book.html">Join</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <div class="hero">
      <div class="hero-card">
        <h1>Careful scent work for everyday reset</h1>
        <p class="lead">Short guided sessions, small bespoke blends, and a seasonal cohort that may support steadier emotional routines. Choose what fits your rhythm.</p>

        <section class="mood" aria-label="Mood to Method">
          <label style="font-weight:600">How are you feeling right now?</label>
          <div class="chips" role="list">
            <div class="chip" data-key="tense" role="listitem">Tight / Wired</div>
            <div class="chip" data-key="drained" role="listitem">Low Energy</div>
            <div class="chip" data-key="foggy" role="listitem">Foggy / Distracted</div>
            <div class="chip" data-key="joyful" role="listitem">Upbeat / Celebrating</div>
          </div>

          <div class="recommend" id="recommend">
            <div>
              <div class="rec-title" id="rec-title">Choose a feeling above</div>
              <div class="rec-desc" id="rec-desc">We'll suggest a method and the right-sized session.</div>
            </div>
            <div class="cta">
              <button class="btn" id="mood-cta">Plan a Session</button>
            </div>
          </div>
        </section>

        <section class="pricing">
          <div style="display:flex;align-items:center;justify-content:space-between">
            <div style="font-weight:600">Compare formats</div>
            <div class="toggle" role="tablist" aria-label="Pricing toggle">
              <button id="opt-monthly" class="active">Monthly</button>
              <button id="opt-package">Package</button>
            </div>
          </div>

          <div class="plan-grid" id="plans">
            <div class="plan">
              <div class="muted">Mini Reset</div>
              <div class="price" data-monthly="25" data-package="110">$25</div>
              <div class="muted">10–20 min guided ritual</div>
            </div>
            <div class="plan">
              <div class="muted">Deep Aroma</div>
              <div class="price" data-monthly="95" data-package="420">$95</div>
              <div class="muted">60 min integrative session</div>
            </div>
            <div class="plan">
              <div class="muted">Scent Strategy</div>
              <div class="price" data-monthly="140" data-package="640">$140</div>
              <div class="muted">90 min session + home plan</div>
            </div>
          </div>
        </section>

        <p style="margin-top:14px;font-size:13px;color:var(--muted)">Safety note: Essential oils are potent. We recommend dilution guidance, a patch test, and discussing pregnancy, nursing, medication, or pet exposure before use. Individual responses vary; these services may support wellbeing, not replace medical care.</p>
      </div>

      <aside class="hero-card">
        <h3 style="margin-top:0">Cohort option</h3>
        <p class="muted">Join a 6-week small-group course focused on seasonal scent rhythms and peer support. Designed for a guided, shared learning experience that may support habit change.</p>
        <div style="margin-top:12px">
          <strong style="display:block">Next cohort starts:</strong>
          <div class="muted">April 2026 • Limited to 10 people</div>
          <button class="btn" style="margin-top:12px" onclick="location.href='book.html'">Reserve a spot</button>
        </div>
        <div style="margin-top:18px;font-size:13px;color:var(--muted)">Have questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</div>
      </aside>
    </div>

    <footer>
      A friendly reminder: We provide safety guidance for dilution, patch testing, and pets. If pregnant or breastfeeding, consult your provider before using essential oils.
    </footer>
  </main>

  <svg class="pattern" width="220" height="220" viewBox="0 0 220 220" xmlns="http://www.w3.org/2000/svg" aria-hidden>
    <defs>
      <linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#F0EBFF"/><stop offset="1" stop-color="#F9F8FF"/></linearGradient>
    </defs>
    <rect width="220" height="220" rx="18" fill="url(#g1)"/>
    <g fill="#F3EFFF" opacity="0.7">
      <circle cx="40" cy="40" r="26"/>
      <circle cx="120" cy="60" r="14"/>
      <circle cx="180" cy="140" r="34"/>
    </g>
  </svg>

  <script>
    // Mood-to-Method mapping
    const mapping = {
      tense: {title: 'Mini Reset', desc: 'A 12-minute guided breathing + targeted aroma to ease tension. Includes simple dilution instructions.', cta: 'Book a Mini Reset', href: 'book.html?type=minireset'},
      drained: {title: 'Aroma Boost', desc: 'An energizing 30-minute protocol with a pick-me-up blend you can take home.', cta: 'Reserve an Aroma Boost', href: 'book.html?type=boost'},
      foggy: {title: 'Deep Aroma', desc: 'A 60-minute focused session to orient attention and create a scent plan for focus routines.', cta: 'Reserve Deep Aroma', href: 'book.html?type=deep'},
      joyful: {title: 'Blend & Plan', desc: 'Create a celebratory blend and a short ritual you can repeat for special moments.', cta: 'Create a Blend', href: 'shop.html'}
    };

    document.querySelectorAll('.chip').forEach(chip => {
      chip.addEventListener('click', () => {
        document.querySelectorAll('.chip').forEach(c=>c.classList.remove('active'));
        chip.classList.add('active');
        const key = chip.getAttribute('data-key');
        const info = mapping[key];
        document.getElementById('rec-title').textContent = info.title;
        document.getElementById('rec-desc').textContent = info.desc + ' (May support emotional balance.)';
        const cta = document.getElementById('mood-cta');
        cta.textContent = info.cta;
        cta.onclick = ()=> location.href = info.href;
      });
    });

    // Pricing comparator with animated numbers
    function animateNumber(el, from, to, duration=600){
      const start = performance.now();
      function step(now){
        const t = Math.min(1,(now-start)/duration);
        const val = Math.round(from + (to-from) * t);
        el.textContent = '$' + val;
        if(t<1) requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    }

    const monthlyBtn = document.getElementById('opt-monthly');
    const packageBtn = document.getElementById('opt-package');
    const priceEls = document.querySelectorAll('.plan .price');

    function setMode(mode){
      monthlyBtn.classList.toggle('active', mode==='monthly');
      packageBtn.classList.toggle('active', mode==='package');
      priceEls.forEach(el => {
        const from = parseInt(el.textContent.replace('$',''))||0;
        const to = parseInt(el.dataset[mode]);
        animateNumber(el, from, to);
      });
    }

    monthlyBtn.addEventListener('click', ()=> setMode('monthly'));
    packageBtn.addEventListener('click', ()=> setMode('package'));

    // init
    setMode('monthly');
  </script>
</body>
</html>"} 
