    nav{display:flex;gap:10px}
    nav a{color:var(--muted);text-decoration:none;padding:7px 10px;border-radius:8px}
    nav a:hover{background:#fff;box-shadow:0 6px 18px rgba(0,0,0,0.06);color:var(--ink)}

