<body>
  <header>
    <div class="logo">
      <svg viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg"><rect width="48" height="48" rx="10" fill="#FFF5F4"/><path d="M24 14c3 0 5.5 2.5 5.5 5.5S27 25 24 25s-5.5-2.5-5.5-5.5S21 14 24 14z" stroke="#FF6B6B" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>
      <div><strong>{{BUSINESS_NAME}}</strong><div class="muted">Blends & Gentle Rituals</div></div>
    </div>
    <nav>
      <a href="index.html">Explore</a>
      <a href="services.html">Offerings</a>
      <a class="active" href="blends.html">Blends & Rituals</a>
      <a href="shop.html">Store</a>
      <a href="book.html">Join</a>
    </nav>
  </header>

  <main>
    <div class="grid">
      <div>
        <h2 style="margin-top:0">Blend collection</h2>
        <p class="muted">Small-batch aroma blends crafted to support moments: calm, clarity, energy, and comfort. Use as inhalers, diluted roll-ons, or added to a diffuser. Follow dilution guidance and patch testing.</p>

        <div class="catalog" id="blend-list">
          <div class="card" data-key="calm">
            <h4>Evening Ease</h4>
            <div class="muted">Warm floral + soft resin. May support settling into rest.</div>
            <div style="margin-top:10px"><button class="btn" onclick="addToCart('Evening Ease')">Add to cart</button></div>
          </div>
          <div class="card" data-key="focus">
            <h4>Clear Path</h4>
            <div class="muted">Herb-forward, bright citrus lift. May support attention and flow.</div>
            <div style="margin-top:10px"><button class="btn" onclick="addToCart('Clear Path')">Add to cart</button></div>
          </div>
          <div class="card" data-key="boost">
            <h4>Morningshine</h4>
            <div class="muted">Uplifting citrus + green notes. May support a gentle energy lift.</div>
            <div style="margin-top:10px"><button class="btn" onclick="addToCart('Morningshine')">Add to cart</button></div>
          </div>
          <div class="card" data-key="comfort">
            <h4>Hearthblend</h4>
            <div class="muted">Warm spice + vanilla amber. May support comfort in tense moments.</div>
            <div style="margin-top:10px"><button class="btn" onclick="addToCart('Hearthblend')">Add to cart</button></div>
          </div>
        </div>

        <section style="margin-top:18px">
          <h3>Short ritual ideas</h3>
          <ul class="muted">
            <li>2–3 inhalations from a hand roller before a meeting;</li>
            <li>Diffuse a small burst while journaling for 8 minutes;</li>
            <li>Apply a diluted roll-on to wrists for a calming anchor.</li>
          </ul>
          <p class="muted">Always dilute essential oils appropriately. Keep blends away from pets' breathing zones; consult your provider if pregnant or nursing.</p>
        </section>
      </div>

      <aside class="mood-panel">
        <h3 style="margin:0">Mood-to-Method</h3>
        <p class="muted">Tell us how you're feeling and we'll suggest a blend and a simple ritual.</p>
        <div class="selects">
          <select id="mood-select" aria-label="Select current mood">
            <option value="choose">Choose a feeling...</option>
            <option value="tense">Tight / Anxious</option>
            <option value="low">Low / Drained</option>
            <option value="foggy">Foggy / Distracted</option>
            <option value="celebrate">Playful / Celebrating</option>
          </select>

          <div style="background:#fff;padding:10px;border-radius:10px;min-height:90px" id="mood-reco">
            <strong class="muted">Suggestion will appear here.</strong>
            <div id="blend-cta" style="margin-top:10px"></div>
          </div>

          <a class="btn" id="mood-action" href="shop.html">Explore blends</a>
        </div>

        <div style="margin-top:12px;font-size:13px;color:var(--muted)">We include dilution ratios and a quick patch-test guide with each blend. If you have pets at home, please check safety notes.</div>
      </aside>
    </div>

    <footer>
      Questions about mixing? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a>.
    </footer>
  </main>

  <script>
    // Simple addToCart stub
    function addToCart(name){
      alert(name + ' added to cart (mock).');
    }

    // Mood-to-Method on blends page
    const moodMap = {
      tense: {blend: 'Evening Ease', ritual: '3 slow breaths while inhaling from a roller; dilute at 1% for skin use.', cta: 'Request a calming consult', href: 'book.html?topic=calm'},
      low: {blend: 'Morningshine', ritual: 'Diffuse 20 minutes in the morning; dilute to 2% for a roll-on.', cta: 'Book an energy check', href: 'book.html?topic=energy'},
      foggy: {blend: 'Clear Path', ritual: 'Inhale from a cotton draw for 5 minutes before focused work.', cta: 'Reserve a focus session', href: 'book.html?topic=focus'},
      celebrate: {blend: 'Hearthblend', ritual: 'Spritz lightly on linens or an inhaler for a celebratory anchor.', cta: 'Order a custom celebratory blend', href: 'shop.html'}
    };

    const sel = document.getElementById('mood-select');
    sel.addEventListener('change', ()=>{
      const v = sel.value;
      const panel = document.getElementById('mood-reco');
      const action = document.getElementById('mood-action');
      if(v==='choose'){panel.innerHTML = '<strong class="muted">Suggestion will appear here.</strong>'; action.href='shop.html'; action.textContent='Explore blends'; return}
      const s = moodMap[v];
      panel.innerHTML = '<div style="font-weight:700">Try: '+s.blend+'</div><div class="muted" style="margin-top:6px">'+s.ritual+'</div>';
      action.textContent = s.cta;
      action.href = s.href;
    });
  </script>
</body>
</html>"} 
{"path":"shop.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Store — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfff7;--card:#ffffff;--accent:#2db26f;--muted:#55606a}
    *{box-sizing:border-box;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto}
    body{margin:0;background:var(--bg);color:#12222b}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 22px}
    nav a{color:var(--muted);text-decoration:none;margin-left:10px}
    main{max-width:1100px;margin:18px auto;padding:20px}
    .hero{display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,#fff,#f7fffb);padding:18px;border-radius:12px}
    .products{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:14px}
    .product{background:var(--card);padding:12px;border-radius:10px;border:1px solid rgba(0,0,0,0.04)}
