  </style>
</head>
<body>
  <header>
    <div><strong>{{BUSINESS_NAME}}</strong> <span class="muted">— small batch blends & tools</span></div>
    <nav>
      <a href="index.html">Explore</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends</a>
      <a class="active" href="shop.html">Store</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <div class="hero">
      <div>
        <h2 style="margin:0">Shop essentials</h2>
        <p class="muted" style="margin:6px 0">Roll-ons, inhalers, diffusers, and curated blends. Each product comes with safety and dilution notes.</p>
      </div>
      <div>
        <span class="muted">Price view:</span>
        <div class="toggle" role="tablist">
          <button id="view-one" class="active">Single</button>
          <button id="view-bundle">Bundle</button>
        </div>
      </div>
    </div>

    <div class="products" id="product-grid">
      <div class="product">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <div>
            <div style="font-weight:700">Roll-on: Calm</div>
            <div class="muted">10 ml; diluted for topical use</div>
          </div>
          <div class="price" data-single="18" data-bundle="64">$18</div>
        </div>
        <div style="margin-top:8px"><button onclick="addToCart('Roll-on: Calm')">Add</button></div>
      </div>

      <div class="product">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <div>
            <div style="font-weight:700">Inhaler: Focus</div>
            <div class="muted">Pocket inhaler for quick lifts</div>
          </div>
          <div class="price" data-single="12" data-bundle="40">$12</div>
        </div>
        <div style="margin-top:8px"><button onclick="addToCart('Inhaler: Focus')">Add</button></div>
      </div>

      <div class="product">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <div>
            <div style="font-weight:700">Blend: Hearthblend (15ml)</div>
            <div class="muted">Warm, grounding aroma</div>
          </div>
          <div class="price" data-single="28" data-bundle="98">$28</div>
        </div>
        <div style="margin-top:8px"><button onclick="addToCart('Hearthblend')">Add</button></div>
      </div>
    </div>

    <section style="margin-top:18px;background:#fff;padding:12px;border-radius:10px">
      <h3 style="margin:0">Why bundles?</h3>
      <p class="muted">Bundles save you money while giving options for short rituals at home. Bundles are priced for a 3-product set and ship with usage notes and dilution guidance. We never advise direct undiluted skin application.</p>
    </section>

    <footer>
      Shipping & returns • Safety: patch test, dilute, keep out of reach of children and pets' breathing zones. If pregnant or breastfeeding, consult your healthcare provider before use.
    </footer>
  </main>

  <script>
    function addToCart(name){
      alert(name + ' — added to cart (demo).');
    }

    // Pricing comparator animated numbers
    function animate(el, from, to){
      const start = performance.now();
      const dur = 500;
      function tick(now){
        const t = Math.min(1,(now-start)/dur);
        el.textContent = '$' + Math.round(from + (to - from) * t);
        if(t < 1) requestAnimationFrame(tick);
      }
      requestAnimationFrame(tick);
    }

    const oneBtn = document.getElementById('view-one');
    const bundleBtn = document.getElementById('view-bundle');
    const prices = document.querySelectorAll('.product .price');

    function setView(mode){
      oneBtn.classList.toggle('active', mode==='single');
      bundleBtn.classList.toggle('active', mode==='bundle');
      prices.forEach(p => {
        const current = parseInt(p.textContent.replace('$',''))||0;
        const target = parseInt(p.dataset[mode]);
        animate(p, current, target);
      });
    }

    oneBtn.addEventListener('click', ()=> setView('single'));
    bundleBtn.addEventListener('click', ()=> setView('bundle'));

    // init
    setView('single');
  </script>
